55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	const CURSE_SURCHARGE_RATE = 0.5;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
60	const LOYALTY_THRESHOLD_YEARS = 2;
61	const LOYALTY_DISCOUNT_RATE = 0.2;
62	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
63	
64	const BASE_PREMIUMS: Record<string, number> = {
65	  sword: 100,
66	  amulet: 60,
67	  staff: 80,
68	  potion: 40,
69	  rune: 25,
70	  moonstone: 25,
71	};
72	
73	const BLOCK_SIZE = 3;
74	const BLOCK_BASE_PREMIUM = 60;
75	
76	const countByType = (items: Item[]): Map<string, number> => {
77	  const counts = new Map<string, number>();
78	  for (const item of items) {
79	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
80	  }
81	  return counts;
82	};
83	
84	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
85	
86	const basePremiumOfGroup = (type: string, count: number): number =>
87	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);
88	
89	const policyBasePremium = (items: Item[]): number =>
90	  [...countByType(items)].reduce(
91	    (total, [type, count]) => total + basePremiumOfGroup(type, count),
92	    0,
93	  );
94	
95	const firstInsuranceSurcharge = (policyBase: number): number =>
96	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
97	
98	const itemBasePremium = (item: Item): number => basePremiumOfType(item.type);
99	
100	const isCursed = (item: Item): boolean => item.cursed === true;
101	
102	const isHighlyEnchanted = (item: Item): boolean =>
103	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
104	
105	const curseSurcharge = (item: Item): number =>
106	  isCursed(item) ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;
107	
108	const highEnchantmentSurcharge = (item: Item): number =>
109	  isHighlyEnchanted(item)
110	    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
111	    : 0;
112	
113	const itemSurchargeTotal = (items: Item[]): number =>
114	  items.reduce(
115	    (total, item) => total + curseSurcharge(item) + highEnchantmentSurcharge(item),
116	    0,
117	  );
118	
119	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
120	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
121	    ? policyBase * LOYALTY_DISCOUNT_RATE
122	    : 0;
123	
124	const followUpContractDiscount = (policyBase: number, previousQuotes: number): number =>
125	  previousQuotes > 0 ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
126	
127	const quote = (
128	  step: QuoteStep,
129	  customer: Customer,
130	  previousQuotes: number,
131	): QuoteResult => {
132	  const policyBase = policyBasePremium(step.items);
133	  const premiumBeforeRounding =
134	    policyBase +
135	    itemSurchargeTotal(step.items) +
136	    firstInsuranceSurcharge(policyBase) -
137	    loyaltyDiscount(policyBase, customer) -
138	    followUpContractDiscount(policyBase, previousQuotes) +
139	    PROCESSING_FEE;
140	  return { premium: Math.ceil(premiumBeforeRounding) };
141	};
142	
143	export const runScenario = (scenario: Scenario): ScenarioOutput => {
144	  let quotesSoFar = 0;
145	  const results = scenario.steps.map((step) => {
146	    const result = quote(step as QuoteStep, scenario.customer, quotesSoFar);
147	    quotesSoFar += 1;
148	    return result;
149	  });
150	  return { results };
151	};
